                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 5 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            # Fill the hollow center of the open-topped container.
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            # The one-cell opening in the top rim spills left across the row above.
            openings = [x for x in range(c0 + 1, c1)
                        if grid[r0][x] == 0 and r0 + 1 <= r1 and grid[r0 + 1][x] == 5]
            if openings:
